using System.ComponentModel.DataAnnotations;

namespace DocSummary.Models;

public class SummarizeRequest
{
    [Required]
    [MinLength(1)]
    public string DocumentText { get; set; } = string.Empty;

    /// <summary>
    /// Maximum number of sentences in the summary. Defaults to 3.
    /// </summary>
    [Range(1, 20)]
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public string Summary { get; set; } = string.Empty;
    public int OriginalLength { get; set; }
    public int SummaryLength { get; set; }
}

namespace DocSummary.Services;

public interface IDocumentSummaryService
{
    string Summarize(string documentText, int maxSentences);
}

using System.Text.RegularExpressions;

namespace DocSummary.Services;

/// <summary>
/// A simple extractive summarizer that scores sentences by word frequency
/// and returns the top-ranked ones in their original order.
/// </summary>
public partial class ExtractiveSummaryService : IDocumentSummaryService
{
    private static readonly HashSet<string> StopWords = new(StringComparer.OrdinalIgnoreCase)
    {
        "a","an","the","is","are","was","were","be","been","being",
        "have","has","had","do","does","did","will","would","shall","should",
        "may","might","must","can","could","and","but","or","nor","not",
        "so","yet","both","either","neither","each","every","all","any",
        "few","more","most","other","some","such","no","only","own","same",
        "than","too","very","just","because","as","until","while","of","at",
        "by","for","with","about","against","between","through","during",
        "before","after","above","below","to","from","up","down","in","out",
        "on","off","over","under","again","further","then","once","here",
        "there","when","where","why","how","what","which","who","whom",
        "this","that","these","those","i","me","my","myself","we","our",
        "ours","ourselves","you","your","yours","yourself","yourselves",
        "he","him","his","himself","she","her","hers","herself","it","its",
        "itself","they","them","their","theirs","themselves"
    };

    [GeneratedRegex(@"(?<=[.!?])\s+", RegexOptions.Compiled)]
    private static partial Regex SentenceSplitter();

    [GeneratedRegex(@"[^\w\s]")]
    private static partial Regex PunctuationStripper();

    public string Summarize(string documentText, int maxSentences)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(documentText);
        ArgumentOutOfRangeException.ThrowIfLessThan(maxSentences, 1);

        var sentences = SentenceSplitter()
            .Split(documentText)
            .Where(s => !string.IsNullOrWhiteSpace(s))
            .ToList();

        if (sentences.Count <= maxSentences)
            return string.Join(" ", sentences);

        // Build word-frequency map (excluding stop words)
        var wordFrequency = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var sentence in sentences)
        {
            foreach (var word in ExtractWords(sentence))
            {
                if (!StopWords.Contains(word))
                    wordFrequency[word] = wordFrequency.GetValueOrDefault(word) + 1;
            }
        }

        // Score each sentence by summing the frequencies of its words
        var scored = sentences
            .Select((text, index) => (Index: index, Text: text, Score: ScoreSentence(text, wordFrequency)))
            .ToList();

        var topIndices = scored
            .OrderByDescending(s => s.Score)
            .Take(maxSentences)
            .Select(s => s.Index)
            .OrderBy(i => i) // preserve original order
            .ToHashSet();

        var summarySentences = scored
            .Where(s => topIndices.Contains(s.Index))
            .OrderBy(s => s.Index)
            .Select(s => s.Text.Trim());

        return string.Join(" ", summarySentences);
    }

    private static double ScoreSentence(string sentence, Dictionary<string, int> wordFrequency)
    {
        var words = ExtractWords(sentence);
        if (words.Count == 0)
            return 0;

        double total = words.Sum(w => wordFrequency.GetValueOrDefault(w));
        // Normalize by word count to avoid bias toward long sentences
        return total / words.Count;
    }

    private static List<string> ExtractWords(string text)
    {
        var cleaned = PunctuationStripper().Replace(text, "");
        return cleaned.Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(w => w.Length > 1)
            .ToList();
    }
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummaryController(IDocumentSummaryService summaryService) : ControllerBase
{
    /// <summary>
    /// Accepts document text and returns a concise extractive summary.
    /// </summary>
    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        var summary = summaryService.Summarize(request.DocumentText, request.MaxSentences);

        return Ok(new SummarizeResponse
        {
            Summary = summary,
            OriginalLength = request.DocumentText.Length,
            SummaryLength = summary.Length
        });
    }
}

